// [WP Restore helper] apply the local wp-backup-*.json download
// Send from your PC with:
//   curl -X POST -H "Content-Type: application/json" --data-binary "@wp-backup-....json" http://<node-red-host>:1880/wpupdate/restore-helper
// Same merge semantics as the tab's internal [Restore backup] (wpu0055):
// every key in the backup overwrites the current value, keys that exist now
// but not in the backup stay, own WPU_ state is never restored.
// NO authentication (http nodes sit outside adminAuth): import, use, delete.
let b = msg.payload;
if (typeof b === "string") {
    try { b = JSON.parse(b); } catch (e) { b = null; }
} else if (typeof Buffer !== "undefined" && Buffer.isBuffer(b)) {
    try { b = JSON.parse(b.toString("utf8")); } catch (e) { b = null; }
} else if (b && typeof b === "object" && b.type === "Buffer" && Array.isArray(b.data)) {
    try { b = JSON.parse(Buffer.from(b.data).toString("utf8")); } catch (e) { b = null; }
}
if (!b || typeof b !== "object" || !b.globalContext || typeof b.globalContext !== "object") {
    msg.statusCode = 400;
    msg.payload = "Not a valid wp-backup file (JSON with a globalContext object). Nothing changed.";
    return msg;
}
const gen = (b.meta && b.meta.generated) ? String(b.meta.generated).slice(0, 19) : "unknown";
let count = 0;
const skipped = [];
for (const k of Object.keys(b.globalContext)) {
    if (k.indexOf("WPU_") === 0) { skipped.push(k); continue; }
    try { global.set(k, b.globalContext[k]); count++; } catch (e) { skipped.push(k); }
}
node.warn("[WP Restore helper] " + count + " settings keys restored from the backup of " + gen + (skipped.length ? "; skipped: " + skipped.join(", ") : "") + ". Delete this helper flow when done.");
msg.statusCode = 200;
msg.payload = "Restored " + count + " settings keys from backup of " + gen + ". Check the WP dashboard and the critical settings (trigger/revert values). Then DELETE this helper flow: it listens on the LAN without authentication.";
return msg;

// [WP Restore helper] surface a runtime error as a readable response
msg.statusCode = 500;
msg.payload = "WP Restore helper error: " + ((msg.error && msg.error.message) ? msg.error.message : "unknown error") + ". Nothing restored unless you saw a success line; check the Node-RED log and try again.";
return msg;
